// src/runtime/middleware.ts
function createContext(init) {
  const store = new Map;
  return {
    request: init.request,
    url: init.url,
    env: init.env,
    executionCtx: init.executionCtx,
    params: init.params,
    json: (body, init2) => Response.json(body, toInit(init2)),
    text: (body, init2) => {
      const ri = toInit(init2);
      return new Response(body, {
        ...ri,
        headers: {
          "content-type": "text/plain; charset=utf-8",
          ...ri?.headers
        }
      });
    },
    html: (body, init2) => {
      const ri = toInit(init2);
      return new Response(body, {
        ...ri,
        headers: {
          "content-type": "text/html; charset=utf-8",
          ...ri?.headers
        }
      });
    },
    redirect: (location, status = 302) => new Response(null, { status, headers: { location } }),
    set: (key, value) => {
      store.set(key, value);
    },
    get: (key) => store.get(key)
  };
}
function toInit(v) {
  if (v === undefined)
    return;
  if (typeof v === "number")
    return { status: v };
  return v;
}
async function compose(stack, ctx, finalize) {
  let index = -1;
  const dispatch = async (i) => {
    if (i <= index) {
      throw new Error("next() called multiple times in a middleware");
    }
    index = i;
    if (i === stack.length)
      return finalize();
    return await stack[i](ctx, () => dispatch(i + 1));
  };
  return dispatch(0);
}
export {
  createContext,
  compose
};
